import gurobipy as gp
from gurobipy import GRB

model = gp.Model(env=env)

# Parameters
products = ['I', 'II', 'III']
quarters = [1, 2, 3, 4]
hours = {'I': 2, 'II': 4, 'III': 3}
compensation = {'I': 20, 'II': 20, 'III': 10}
inventory_cost = 5
capacity = 15000
final_inventory = 150

# Decision variables
prod = {}
inv = {}
back = {}

for i in products:
    for q in quarters:
        prod[(i, q)] = model.addVar(lb=0, name=f"prod_{i}_q{q}")
        inv[(i, q)] = model.addVar(lb=0, name=f"inv_{i}_q{q}")
        back[(i, q)] = model.addVar(lb=0, name=f"back_{i}_q{q}")

# Demand
demand = {
    ('I', 1): 1500, ('I', 2): 1000, ('I', 3): 2000, ('I', 4): 1200,
    ('II', 1): 1500, ('II', 2): 1500, ('II', 3): 1200, ('II', 4): 1500,
    ('III', 1): 1000, ('III', 2): 2000, ('III', 3): 1500, ('III', 4): 2500
}

# Inventory balance constraints
for i in products:
    for q in quarters:
        prev_inv = inv[(i, q-1)] if q > 1 else 0
        prev_back = back[(i, q-1)] if q > 1 else 0
        model.addConstr(
            inv[(i, q)] - back[(i, q)] == prev_inv + prod[(i, q)] - demand[(i, q)] - prev_back,
            name=f"balance_{i}_q{q}"
        )

# Production capacity constraints
for q in quarters:
    model.addConstr(
        sum(hours[i] * prod[(i, q)] for i in products) <= capacity,
        name=f"capacity_q{q}"
    )

# Product I cannot be produced in Q2
model.addConstr(prod[('I', 2)] == 0, name="no_prod_I_q2")

# Final inventory requirements
for i in products:
    model.addConstr(inv[(i, 4)] == final_inventory, name=f"final_inv_{i}")
    model.addConstr(back[(i, 4)] == 0, name=f"no_back_{i}")

# Objective: minimize total cost (inventory + compensation)
model.setObjective(
    sum(inventory_cost * inv[(i, q)] + compensation[i] * back[(i, q)] 
          for i in products for q in quarters),
    GRB.MINIMIZE
)

model.optimize()

if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")
