import gurobipy as gp
from gurobipy import GRB

model = gp.Model(env=env)

# Define workers and tasks
workers = ['I', 'II', 'III', 'IV', 'V']
tasks = ['A', 'B', 'C', 'D']

# Define cost matrix (hours)
costs = {
    'I': {'A': 9, 'B': 4, 'C': 3, 'D': 7},
    'II': {'A': 4, 'B': 6, 'C': 5, 'D': 6},
    'III': {'A': 5, 'B': 4, 'C': 7, 'D': 5},
    'IV': {'A': 7, 'B': 5, 'C': 2, 'D': 3},
    'V': {'A': 10, 'B': 6, 'C': 7, 'D': 4}
}

# Create binary decision variables x[w][t]
x = {}
for w in workers:
    for t in tasks:
        x[(w, t)] = model.addVar(vtype=GRB.BINARY, name=f"x_{w}_{t}")

# Constraint: Each task must be assigned to exactly one worker
for t in tasks:
    model.addConstr(gp.quicksum(x[(w, t)] for w in workers) == 1, name=f"task_{t}")

# Constraint: Each worker can be assigned to at most one task
for w in workers:
    model.addConstr(gp.quicksum(x[(w, t)] for t in tasks) <= 1, name=f"worker_{w}")

# Objective: Minimize total working hours
model.setObjective(gp.quicksum(costs[w][t] * x[(w, t)] for w in workers for t in tasks), GRB.MINIMIZE)

model.optimize()

if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")

