x = {}
for i in range(1, 8):
    for j in range(1, 8):
        if i != j:
            x[(i,j)] = model.addVar(vtype=GRB.BINARY, name=f"x_{i}_{j}")

# MTZ formulation: u[i] for each node (except depot at 1)
u = {}
for i in range(2, 8):
    u[i] = model.addVar(lb=2, ub=7, vtype=GRB.CONTINUOUS, name=f"u_{i}")

# Each node has exactly one outgoing edge
for i in range(1, 8):
    model.addConstr(gp.quicksum(x[(i,j)] for j in range(1, 8) if i != j) == 1, name=f"out_{i}")

# Each node has exactly one incoming edge
for j in range(1, 8):
    model.addConstr(gp.quicksum(x[(i,j)] for i in range(1, 8) if i != j) == 1, name=f"in_{j}")

# Subtour elimination constraints (MTZ)
for i in range(2, 8):
    for j in range(2, 8):
        if i != j:
            model.addConstr(u[j] - u[i] + 7 * x[(i,j)] <= 6, name=f"mtz_{i}_{j}")

# Objective: minimize total distance
model.setObjective(gp.quicksum(dist[(i,j)] * x[(i,j)] for i in range(1, 8) for j in range(1, 8) if i != j), GRB.MINIMIZE)

model.optimize()

if model.Status == GRB.OPTIMAL:
